const esc=s=>String(s??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
async function selectRows(table,query=""){return api("/rest/v1/"+table+"?select=*"+query,{method:"GET"});}
