async function loadClubs(){showSkeleton("clubsTable",3);showSkeleton("teamsTable",3);try{[clubsData,teamsData]=await Promise.all([selectRows("clubs","&order=name.asc"),selectRows("teams","&order=name.asc")]);renderClubs()}catch(e){$("clubsTable").innerHTML='<div class="empty-state">'+esc(tr("loadError"))+'</div>';throw e}}
