let matchesData=[],competitionsData=[],editingMatch=null,finishingMatch=null;
async function loadMatches(){showSkeleton("matchesTable",4);try{[matchesData,teamsData,competitionsData]=await Promise.all([selectRows("matches","&order=match_date.desc"),selectRows("teams","&order=name.asc"),selectRows("competitions","&order=name.asc")]);renderMatches()}catch(e){$("matchesTable").innerHTML='<div class="empty-state">'+esc(tr("loadError"))+'</div>';throw e}}
function renderMatches(){$("matchesCount").textContent=matchesData.length;$("matchTeam").innerHTML=teamsData.map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join("");$("matchCompetition").innerHTML='<option value="">—</option>'+competitionsData.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join("");const status={scheduled:tr("scheduled"),postponed:tr("postponed"),cancelled:tr("cancelled"),finished:tr("finished")};$("matchesTable").innerHTML=tableHtml(["matchCol","dateCol","teamCol","resultCol","statusCol","actions"],matchesData.map(m=>{const tm=teamsData.find(t=>t.id===m.team_id);const d=new Date(m.match_date);const dt=isNaN(d)?m.match_date:d.toLocaleString(lang==="ar"?"ar-MA":"fr-FR",{dateStyle:"medium",timeStyle:"short"});return '<tr><td><span class="table-title">'+esc(m.opponent_name)+'</span><span class="table-sub">'+esc(m.venue||"—")+'</span></td><td>'+esc(dt)+'</td><td>'+esc(tm?.name||"—")+'</td><td><b>'+esc(m.status==="finished"?m.goals_for+" - "+m.goals_against:"—")+'</b></td><td><span class="status-pill">'+esc(status[m.status]||m.status)+'</span></td><td><div class="row-actions">'+(m.status==="finished"?'<button data-reopen-match="'+m.id+'">'+esc(tr("reopen"))+'</button>':'<button data-finish-match="'+m.id+'">'+esc(tr("finishMatch"))+'</button>')+'<button data-lineup-match="'+m.id+'">'+esc(tr("lineup"))+'</button>'+ '<button data-events-match="'+m.id+'">'+esc(tr("matchEvents"))+'</button>'+ '<button data-edit-match="'+m.id+'">'+esc(tr("edit"))+'</button><button class="danger" data-delete-match="'+m.id+'">'+esc(tr("delete"))+'</button></div></td></tr>'}))}
