$("matchesTable").addEventListener("click",async e=>{const edit=e.target.closest("[data-edit-match]"),del=e.target.closest("[data-delete-match]"),finish=e.target.closest("[data-finish-match]"),reopen=e.target.closest("[data-reopen-match]");if(edit){const m=matchesData.find(x=>x.id===edit.dataset.editMatch);if(!m)return;editingMatch=m.id;$("matchTeam").value=m.team_id;$("matchOpponent").value=m.opponent_name;$("matchCompetition").value=m.competition_id||"";$("matchDate").value=new Date(m.match_date).toISOString().slice(0,16);$("matchVenue").value=m.venue||"";$("matchDuration").value=m.duration_minutes;$("matchHomeAway").value=m.home_away;$("matchStatus").value=m.status==="finished"?"scheduled":m.status;$("matchPublic").checked=!!m.is_public;$("matchEditorTitle").textContent=tr("edit")+" — "+m.opponent_name;openEditor("matchEditor")}if(del&&confirm(tr("confirmDeleteMatch"))){try{await deleteRow("matches",del.dataset.deleteMatch);await loadMatches();loadDashboard()}catch{alert(tr("saveError"))}}const lu=e.target.closest("[data-lineup-match]");if(lu){const m=matchesData.find(x=>x.id===lu.dataset.lineupMatch);if(m){try{await loadLineup(m)}catch{alert(tr("loadError"))}}}const events=e.target.closest("[data-events-match]");if(events){const m=matchesData.find(x=>x.id===events.dataset.eventsMatch);if(m){try{await loadMatchEvents(m)}catch{alert(tr("loadError"))}}}if(finish){finishingMatch=finish.dataset.finishMatch;$("resultFor").value="";$("resultAgainst").value="";$("matchReport").value="";openEditor("resultEditor")}if(reopen&&confirm(tr("confirmReopen"))){try{const m=matchesData.find(x=>x.id===reopen.dataset.reopenMatch);await saveRow("matches",{status:"scheduled",finalized_at:null},reopen.dataset.reopenMatch);if(m)await syncTeamAvailability(m.team_id);await loadMatches();loadDashboard()}catch{alert(tr("saveError"))}}});
