let competitionRows=[],competitionEntries=[],selectedCompetition=null,editingCompetition=null,editingCompetitionEntry=null;
async function loadCompetitions(){
 showSkeleton("competitionsTable",3);
 const canManage=currentProfile?.role==="manager";
 $("addCompetitionBtn").classList.toggle("hidden",!canManage);
 $("addEntryBtn").classList.toggle("hidden",!canManage);
 if(!canManage){closeEditor("competitionEditor");closeEditor("entryEditor")}
 competitionRows=await selectRows("competitions","&order=name.asc");
 $("competitionsCount").textContent=competitionRows.length;
 $("competitionsTable").innerHTML=tableHtml(["competitionName","season","actions"],competitionRows.map(x=>'<tr><td><b>'+esc(x.name)+'</b></td><td>'+esc(x.season||"—")+'</td><td><div class="row-actions"><button data-open-comp="'+x.id+'">'+esc(tr("standings"))+'</button>'+(canManage?'<button data-edit-comp="'+x.id+'">'+esc(tr("edit"))+'</button><button class="danger" data-delete-comp="'+x.id+'">'+esc(tr("delete"))+'</button>':"")+'</div></td></tr>'));
}
async function openStandings(id){$("addEntryBtn").classList.toggle("hidden",currentProfile?.role!=="manager");selectedCompetition=competitionRows.find(x=>x.id===id);if(!selectedCompetition)return;[competitionEntries,teamsData,matchesData]=await Promise.all([selectRows("competition_teams","&competition_id=eq."+id),selectRows("teams","&order=name.asc"),selectRows("matches","&competition_id=eq."+id+"&order=match_date.asc")]);$("entryTeam").innerHTML='<option value="">—</option>'+teamsData.map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join("");$("standingsTitle").textContent=tr("standings")+" — "+selectedCompetition.name;$("standingsArea").classList.remove("hidden");renderStandings()}
function renderStandings(){const allMatches=matchesData.filter(m=>m.competition_id===selectedCompetition.id);let rows=competitionEntries.map(e=>{let s={played:e.played||0,won:e.won||0,drawn:e.drawn||0,lost:e.lost||0,gf:e.goals_for||0,ga:e.goals_against||0,points:(e.won||0)*selectedCompetition.points_win+(e.drawn||0)*selectedCompetition.points_draw+(e.lost||0)*selectedCompetition.points_loss+(e.manual_points||0)};let remaining=e.team_id?0:(e.remaining_matches||0);if(e.team_id){const ms=allMatches.filter(m=>m.team_id===e.team_id),done=ms.filter(m=>m.status==="finished");remaining=ms.filter(m=>["scheduled","in_progress","postponed"].includes(m.status)).length;s={played:done.length,won:0,drawn:0,lost:0,gf:0,ga:0,points:e.manual_points||0};done.forEach(m=>{s.gf+=m.goals_for||0;s.ga+=m.goals_against||0;if(m.goals_for>m.goals_against){s.won++;s.points+=selectedCompetition.points_win}else if(m.goals_for===m.goals_against){s.drawn++;s.points+=selectedCompetition.points_draw}else{s.lost++;s.points+=selectedCompetition.points_loss}})}return {entry:e,s,remaining,name:e.team_id?(teamsData.find(t=>t.id===e.team_id)?.name||"—"):e.opponent_name}}).sort((a,b)=>b.s.points-a.s.points||(b.s.gf-b.s.ga)-(a.s.gf-a.s.ga)||b.s.gf-a.s.gf||a.name.localeCompare(b.name));$("standingsTable").innerHTML=tableHtml(["nameCol","played","remainingMatches","won","drawn","lost","goalsForShort","goalsAgainstShort","goalDifference","points","actions"],rows.map((r,i)=>'<tr><td><b>'+(i+1)+'. '+esc(r.name)+'</b></td><td>'+r.s.played+'</td><td>'+r.remaining+'</td><td>'+r.s.won+'</td><td>'+r.s.drawn+'</td><td>'+r.s.lost+'</td><td>'+r.s.gf+'</td><td>'+r.s.ga+'</td><td>'+(r.s.gf-r.s.ga)+'</td><td><b>'+r.s.points+'</b></td><td>'+(currentProfile?.role==="manager"?'<div class="row-actions"><button data-edit-entry="'+r.entry.id+'">'+esc(tr("edit"))+'</button><button class="danger" data-delete-entry="'+r.entry.id+'">'+esc(tr("delete"))+'</button></div>':"—")+'</td></tr>'));const target=Number(selectedCompetition.target_position)||0,box=$("targetProjection");if(!target){box.classList.add("hidden");box.innerHTML="";return}const own=rows.map((r,i)=>({...r,rank:i+1})).filter(r=>r.entry.team_id);box.classList.remove("hidden");if(!own.length){box.innerHTML='<b>'+(lang==="ar"?"حساب المركز المستهدف":"Objectif de classement")+'</b><p class="table-sub">'+(lang==="ar"?"أضف فريقك إلى جدول البطولة لاحتساب فرص بلوغ المركز المستهدف.":"Ajoutez votre équipe au classement pour calculer ses possibilités d’atteindre l’objectif.")+'</p>';return}const cutoff=rows[target-1];box.innerHTML='<b>'+(lang==="ar"?"تقدير بلوغ المركز "+target:"Projection pour la "+target+(target===1?"re":"e")+" place")+'</b>'+own.map(r=>{if(r.rank<=target)return '<div class="attention-item" style="margin-top:10px"><span class="dot" style="background:var(--green)"></span><span><b>'+esc(r.name)+'</b> — '+(lang==="ar"?"الفريق حاليا ضمن المركز المستهدف":"équipe actuellement dans l’objectif")+' ('+r.rank+')</span></div>';if(!cutoff)return '<p class="table-sub">'+esc(r.name)+' — '+(lang==="ar"?"عدد الفرق المسجلة أقل من المركز المستهدف.":"Le nombre d’équipes inscrites est inférieur à l’objectif.")+'</p>';const max=r.s.points+r.remaining*selectedCompetition.points_win,cutoffMax=cutoff.s.points+cutoff.remaining*selectedCompetition.points_win,needed=Math.max(0,cutoffMax-r.s.points+1);let msg;if(!r.remaining)msg=lang==="ar"?"لا توجد مباريات متبقية مسجلة؛ أضف المباريات القادمة لحساب الإمكانية.":"Aucun match restant n’est enregistré ; ajoutez les prochaines rencontres.";else if(max<cutoffMax)msg=lang==="ar"?"غير ممكن حسابيا وفق المباريات المتبقية المسجلة.":"Mathématiquement impossible selon les matchs restants enregistrés.";else if(max===cutoffMax)msg=lang==="ar"?"ممكن عند التعادل في النقاط، ويتوقف الحسم على فارق الأهداف.":"Possible à égalité de points ; la différence de buts sera décisive.";else msg=lang==="ar"?"ما زال بلوغ المركز ممكنا حسابيا.":"L’objectif reste mathématiquement atteignable.";return '<div style="border-top:1px solid var(--line);margin-top:10px;padding-top:10px"><b>'+esc(r.name)+'</b><div class="table-sub">'+(lang==="ar"?"الترتيب الحالي: ":"Classement actuel : ")+r.rank+' · '+(lang==="ar"?"النقاط: ":"Points : ")+r.s.points+' · '+(lang==="ar"?"المباريات المتبقية المسجلة: ":"Matchs restants enregistrés : ")+r.remaining+' · '+(lang==="ar"?"أقصى نقاط ممكنة: ":"Maximum possible : ")+max+'</div><div class="table-sub">'+(lang==="ar"?"النقاط المطلوبة لتجاوز صاحب المركز المستهدف: ":"Points nécessaires pour dépasser le seuil : ")+needed+'</div><div style="font-size:11px;margin-top:6px;color:var(--ice)">'+msg+'</div></div>'}).join("")}
