$("entryForm").addEventListener("submit",async e=>{e.preventDefault();const team=$("entryTeam").value,name=$("entryOpponent").value.trim();if(!team&&!name)return alert(tr("saveError"));if(competitionEntries.some(x=>x.id!==editingCompetitionEntry&&((team&&x.team_id===team)||(!team&&name&&x.opponent_name?.toLowerCase()===name.toLowerCase()))))return alert(tr("duplicateEntry"));const body={competition_id:selectedCompetition.id,team_id:team||null,opponent_name:team?null:name,manual_points:+$("entryPoints").value||0,remaining_matches:+$("entryRemaining").value||0,played:+$("entryPlayed").value||0,won:+$("entryWon").value||0,drawn:+$("entryDrawn").value||0,lost:+$("entryLost").value||0,goals_for:+$("entryGoalsFor").value||0,goals_against:+$("entryGoalsAgainst").value||0};if(body.won+body.drawn+body.lost>body.played)return alert(lang==="ar"?"مجموع الفوز والتعادل والخسارة لا يمكن أن يتجاوز عدد المباريات.":"Le total victoires/nuls/défaites ne peut pas dépasser les matchs joués.");try{await saveRow("competition_teams",body,editingCompetitionEntry);editingCompetitionEntry=null;closeEditor("entryEditor");await openStandings(selectedCompetition.id)}catch{alert(tr("saveError"))}});
$("standingsTable").addEventListener("click",async e=>{const d=e.target.closest("[data-delete-entry]"),ed=e.target.closest("[data-edit-entry]");if(ed){const x=competitionEntries.find(z=>z.id===ed.dataset.editEntry);if(x){editingCompetitionEntry=x.id;$("entryTeam").value=x.team_id||"";$("entryOpponent").value=x.opponent_name||"";$("entryPoints").value=x.manual_points||0;$("entryRemaining").value=x.remaining_matches||0;$("entryPlayed").value=x.played||0;$("entryWon").value=x.won||0;$("entryDrawn").value=x.drawn||0;$("entryLost").value=x.lost||0;$("entryGoalsFor").value=x.goals_for||0;$("entryGoalsAgainst").value=x.goals_against||0;openEditor("entryEditor")}}if(d&&confirm(tr("delete")+"?")){try{await deleteRow("competition_teams",d.dataset.deleteEntry);await openStandings(selectedCompetition.id)}catch{alert(tr("saveError"))}}});

