$("restoreFile").addEventListener("change",async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.app!=="NOUN STAR MANAGER"||!data.tables||typeof data.tables!=="object")throw Error("INVALID");if(!confirm(tr("confirmRestore")))return;const movementItems=new Set((data.tables.equipment_movements||[]).map(m=>m.item_id));const order=["clubs","teams","players","team_players","player_team_history","competitions","competition_teams","matches","match_lineups","match_events","training_sessions","training_drills","training_session_drills","training_attendance","injuries","absences","suspensions","suspension_match_log","settings","finance_dues","club_seasons","sponsors","sponsor_agreements","finance_transactions","sponsor_payments","equipment_items","equipment_movements","club_kits","kit_assignments","club_activity_logs","club_media"];for(const table of order){const rows=data.tables[table];if(!Array.isArray(rows)||!rows.length)continue;const clean=rows.map(row=>{const x={...row};if("owner_id" in x)x.owner_id=session.user.id;if(table==="settings")x.owner_id=session.user.id;if(table==="club_media")x.created_by=session.user.id;if(table==="equipment_items"&&movementItems.has(x.id))x.quantity_on_hand=0;return x});const conflict=table==="settings"?"owner_id":"id";await api("/rest/v1/"+table+"?on_conflict="+conflict,{method:"POST",headers:{"Prefer":"resolution=merge-duplicates,return=minimal"},body:JSON.stringify(clean)})}$("backupMessage").textContent=tr("restoreDone");loadDashboard()}catch{$("backupMessage").textContent=tr("invalidBackup")}finally{$("restoreFile").value=""}});

