 $("clubMovementPlayer").innerHTML=opts(d.players,"بدون لاعب",x=>x.full_name);
 $("clubMovementTeam").innerHTML=opts(d.teams,"بدون فئة",x=>x.name);
 $("clubKitSeason").innerHTML=opts(d.seasons,"بدون ربط بموسم",x=>x.name);
