$("reportCsvBtn").addEventListener("click",()=>{if(!reportExportRows.length){alert("لا توجد سجلات لتصديرها.");return}const cols=[...new Set(reportExportRows.flatMap(x=>Object.keys(x)))];const csv="\uFEFF"+[cols.join(","),...reportExportRows.map(row=>cols.map(k=>'"'+String(row[k]??"").replace(/"/g,'""')+'"').join(","))].join("\r\n");const blob=new Blob([csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="noun-star-report-"+$("reportType").value+"-"+localFinanceDate()+".csv";a.click();URL.revokeObjectURL(url)});

