$("cancelClub").addEventListener("click",()=>{closeEditor("clubEditor");resetClubForm()});
$("clubForm").addEventListener("submit",async e=>{e.preventDefault();const body={name:$("clubName").value.trim(),short_name:$("clubShort").value.trim()||null,notes:$("clubNotes").value.trim()||null};try{await saveRow("clubs",body,editingClub);closeEditor("clubEditor");resetClubForm();await loadClubs();loadDashboard();}catch(err){alert(err.message==="HTTP_409"?tr("clubExists"):tr("saveError"))}});
