async function capturePlayerTeamSnapshot(playerId,teamId){
 const matches=await selectRows("matches","&team_id=eq."+teamId+"&status=eq.finished"),ids=new Set(matches.map(m=>m.id));
 const [lineups,events]=await Promise.all([selectRows("match_lineups","&player_id=eq."+playerId),selectRows("match_events")]);
 const lu=lineups.filter(x=>ids.has(x.match_id)),ev=events.filter(x=>ids.has(x.match_id)&&(x.player_id===playerId||x.related_player_id===playerId));
 const played=new Set(lu.filter(x=>(Number(x.minutes_played)||0)>0).map(x=>x.match_id));
 ev.forEach(x=>{if(x.event_type!=="note")played.add(x.match_id)});
 return {appearances:played.size,minutes:lu.reduce((n,x)=>n+(Number(x.minutes_played)||0),0),goals:ev.filter(x=>x.player_id===playerId&&x.event_type==="goal").length,assists:ev.filter(x=>x.player_id===playerId&&x.event_type==="assist").length,yellow_cards:ev.filter(x=>x.player_id===playerId&&x.event_type==="yellow_card").length,red_cards:ev.filter(x=>x.player_id===playerId&&x.event_type==="red_card").length,captured_at:new Date().toISOString()};
}
