function showStaffBootstrapError(err){
 const code=String(err?.message||"");
 if(code==="SESSION_EXPIRED"||code==="NO_SESSION"){logout(true);$("accountModal").classList.remove("hidden");$("accountChoice").classList.add("hidden");$("staffLoginPanel").classList.remove("hidden");return;}
 $("appView").classList.add("hidden");$("loginView").classList.remove("hidden");$("accountModal").classList.remove("hidden");$("accountChoice").classList.add("hidden");$("staffLoginPanel").classList.remove("hidden");
 $("loginError").textContent=code==="PROFILE_NOT_FOUND"?"تم قبول الدخول، لكن ملف صلاحيات المدير غير متاح. لم نسجل خروجك؛ أعد المحاولة أو تواصل مع الدعم.":/^HTTP_\d+$/.test(code)?"تم قبول الدخول، لكن تعذر تحميل بيانات الإدارة ("+code+"). بقيت الجلسة محفوظة لتشخيص المشكلة.":code==="INVALID_CREDENTIALS"?"بيانات الدخول غير صحيحة. تحقق من الكود وكلمة المرور.":"تعذر فتح لوحة الإدارة ("+(code||"BOOTSTRAP_ERROR")+"). بقيت الجلسة محفوظة؛ أعد المحاولة دون إنشاء حساب جديد.";
 console.error("NOUN STAR staff session bootstrap",err);
}

async function publicRpc(name,body={}){const headers={apikey:CONFIG.publishableKey,Authorization:"Bearer "+(session?.access_token||CONFIG.publishableKey),"Content-Type":"application/json"};const response=await fetch(CONFIG.supabaseUrl+"/rest/v1/rpc/"+name,{method:"POST",headers,body:JSON.stringify(body)});if(!response.ok)throw Error("PUBLIC_RPC_"+response.status);return response.json()}
async function publicRequest(table,query=""){
 const headers={apikey:CONFIG.publishableKey,Authorization:"Bearer "+(session?.access_token||CONFIG.publishableKey)};
 const response=await fetch(CONFIG.supabaseUrl+"/rest/v1/"+table+"?"+query,{headers});
 if(!response.ok)throw Error("PUBLIC_HTTP_"+response.status);
 return response.status===204?null:response.json();
}
