function openPublicGallery(index){if(!publicGalleryItems.length)return;publicGalleryIndex=(index+publicGalleryItems.length)%publicGalleryItems.length;renderPublicGalleryLightbox();const dialog=$("publicGalleryLightbox");if(typeof dialog.showModal==="function")dialog.showModal();else dialog.setAttribute("open","")}
function movePublicGallery(step){if(!publicGalleryItems.length)return;publicGalleryIndex=(publicGalleryIndex+step+publicGalleryItems.length)%publicGalleryItems.length;renderPublicGalleryLightbox()}
async function loadPublicMedia(){const target=$("publicMediaFeed");if(!target)return;try{const rows=await publicRequest("club_media","select=id,media_type,title,caption,storage_path,created_at&visibility=eq.public&consent_confirmed=eq.true&order=created_at.desc&limit=30");publicGalleryItems=rows.map(item=>({url:mediaPublicUrl(item.storage_path),title:item.title||"NOUN STAR",caption:item.caption||"",storagePath:item.storage_path,createdAt:item.created_at}));target.innerHTML=rows.length?rows.map((item,index)=>{const url=mediaPublicUrl(item.storage_path),kind=item.media_type==="player_card"?"تصميم لاعب":"صور مباراة";return '<article class="media-gallery-card"><button type="button" class="media-gallery-image-button" data-open-gallery="'+index+'" aria-label="عرض '+esc(item.title)+'"><img loading="lazy" src="'+esc(url)+'" alt="'+esc(item.title)+'"></button><div class="media-gallery-copy"><span class="public-post-tag">'+kind+'</span><b>'+esc(item.title)+'</b>'+(item.caption?'<p>'+esc(item.caption)+'</p>':'')+'<div class="media-gallery-actions"><button type="button" data-open-gallery="'+index+'">عرض الصورة</button><button type="button" data-share-media="'+esc(item.storage_path)+'" data-share-title="'+esc(item.title)+'">مشاركة</button></div><small class="table-sub">'+esc(mediaDate(item.created_at))+'</small></div></article>'}).join(""):'<div class="public-empty">سيظهر هنا جديد صور اللاعبين والمباريات بعد نشره من إدارة النادي.</div>'}catch(err){target.innerHTML='<div class="public-empty">تعذر تحميل معرض الصور حالياً. حاول لاحقاً.</div>';console.warn("public media feed",err)}}
