$("generatePlayerPosterBtn").addEventListener("click",async()=>{const b=$("generatePlayerPosterBtn");b.disabled=true;try{await generatePlayerPoster()}catch(err){alert(err.message||"تعذر إنشاء التصميم.")}finally{b.disabled=false}});
