$("publishPlayerPosterBtn").addEventListener("click",async()=>{const player=mediaPlayers.find(p=>p.id===$("mediaPlayerChoice").value),status=$("mediaUploadStatus");if(!player||generatedPosterPlayerId!==player.id){alert("أنشئ المعاينة أولاً.");return}if(!$("playerPosterConsent").checked){alert("أكد الحصول على الموافقة قبل النشر.");return}const btn=$("publishPlayerPosterBtn");btn.disabled=true;status.textContent="جارٍ نشر التصميم...";try{const blob=await canvasBlob($("playerPosterCanvas"),"image/webp",.9);if(!blob)throw Error("تعذر تجهيز صورة التصميم.");await uploadPublicMedia(blob,{media_type:"player_card",player_id:player.id,title:"تقديم اللاعب · "+player.full_name,caption:"NOUN STAR FOOTBALL CLUB · "+(player.primary_position||"لاعب"),consent_confirmed:true});$("playerPosterConsent").checked=false;status.textContent="تم نشر تصميم اللاعب في معرض الجمهور.";await loadMediaManager();await loadPublicMedia()}catch(err){status.textContent=err.message||"تعذر نشر التصميم."}finally{btn.disabled=false}});
$("uploadMatchPhotosBtn").addEventListener("click",async()=>{const files=[...$("mediaPhotoFiles").files],status=$("mediaUploadStatus"),match=mediaMatches.find(m=>m.id===$("mediaMatchChoice").value);if(!files.length){alert("اختر صورة واحدة على الأقل.");return}if(files.length>10){alert("يمكن رفع 10 صور في الدفعة الواحدة.");return}if(!$("mediaPhotoConsent").checked){alert("أكد الحصول على موافقات النشر قبل رفع الصور.");return}const btn=$("uploadMatchPhotosBtn");btn.disabled=true;let done=0;status.textContent="جارٍ تجهيز الصور...";try{for(const file of files){const blob=await compressMediaFile(file);await uploadPublicMedia(blob,{media_type:"match_photo",match_id:match?.id||null,title:$("mediaPhotoTitle").value.trim()||(match?"مباراة NOUN STAR ضد "+match.opponent_name:"لقطات من NOUN STAR"),caption:$("mediaPhotoCaption").value.trim(),consent_confirmed:true});done++;status.textContent="تم رفع "+done+" من "+files.length+" صور..."}$("mediaPhotoFiles").value="";$("mediaPhotoConsent").checked=false;status.textContent="اكتمل نشر "+done+" صورة في معرض الجمهور.";await loadMediaManager();await loadPublicMedia()}catch(err){status.textContent="تم رفع "+done+" صور. "+(err.message||"تعذر إكمال الرفع.")}finally{btn.disabled=false}});
